import React, { useEffect, useMemo, useState } from "react";
import "./App.css";
import PondSimulation from "./PondSimulation";
import {
  CUSTOMER_SERVICE,
  isWhatsAppNumber,
  whatsappUrl,
} from "./contact";
import {
  ApiError,
  api,
  clearSession,
  hasSession,
} from "./api/client";
import type {
  ApiFarm,
  ApiFeeding,
  ApiPond,
  ApiReading,
  ApiUser,
  BootstrapData,
} from "./api/types";
type Language = "en" | "ha" | "yo" | "pcm";

type Track =
  | "Fish Farmer"
  | "Veterinary Doctor"
  | "Seller / Supplier"
  | "Enthusiast"
  | "Individual"
  | "Other";

type Page =
  | "welcome"
  | "auth"
  | "dashboard"
  | "farms"
  | "marketplace"
  | "community"
  | "profile";

type User = {
  name: string;
  email: string;
  phone?: string;
  role: Track | string;
  otherRole?: string;
  guest?: boolean;
};

type Farm = {
  id: string;
  name: string;
  location: string;
};

type Pond = {
  id: string;
  farmId: string;
  name: string;
  population: number;
  length: number;
  width: number;
  status: string;
};

type Feeding = {
  id: string;
  pondId: string;
  amount: number;
  date: string;
};

type Reading = {
  id: string;
  pondId: string;
  temperature: number;
  oxygen: number;
  ph: number;
  level: number;
  turbidityNtu?: number | null;
  date: string;
};

type ListingStatus = "available" | "sold";

type Listing = {
  id: string;
  name: string;
  category: string;
  price: number;
  description: string;
  seller: string;
  sellerId?: string;
  sellerPhone?: string;
  status: ListingStatus;
  emoji: string;
};

type Inquiry = {
  id: string;
  listingId: string;
  listingName: string;
  seller: string;
  sellerId?: string;
  sellerPhone?: string;
  buyerName: string;
  buyerPhone: string;
  message: string;
  date: string;
  status: "new" | "responded";
};

type CommunityGroupId =
  | "general"
  | "farmers"
  | "veterinary"
  | "sellers"
  | "enthusiasts";

type Message = {
  id: string;
  sender: string;
  text: string;
  date: string;
  mine?: boolean;
  role?: string;
  group: CommunityGroupId;
};


type AppData = {
  user: User | null;
  language: Language;
  farms: Farm[];
  ponds: Pond[];
  feedings: Feeding[];
  readings: Reading[];
  listings: Listing[];
  messages: Message[];
  inquiries: Inquiry[];
};

const makeId = () =>
  (globalThis.crypto as { randomUUID?: () => string } | undefined)?.randomUUID?.() ??
  `${Date.now()}-${Math.random().toString(36).slice(2)}`;

const today = () => new Date().toISOString().slice(0, 10);

const money = (n: number) => `₦${n.toLocaleString("en-NG")}`;

const accountTypes: Track[] = [
  "Fish Farmer",
  "Veterinary Doctor",
  "Seller / Supplier",
  "Enthusiast",
  "Individual",
  "Other",
];

const communityGroups: {
  id: CommunityGroupId;
  label: string;
  description: string;
}[] = [
  {
    id: "general",
    label: "General",
    description: "Open discussion for everyone in the FishLink community.",
  },
  {
    id: "farmers",
    label: "Farmers",
    description: "Pond management, feeding, growth and daily production.",
  },
  {
    id: "veterinary",
    label: "Veterinary",
    description: "Fish health, disease prevention and expert guidance.",
  },
  {
    id: "sellers",
    label: "Sellers",
    description: "Feed, fingerlings, equipment and market conversations.",
  },
  {
    id: "enthusiasts",
    label: "Enthusiasts",
    description: "Learning, small-scale growing and shared experience.",
  },
];

const communityGroupForRole = (role?: string): CommunityGroupId => {
  switch (role) {
    case "Fish Farmer":
      return "farmers";
    case "Veterinary Doctor":
      return "veterinary";
    case "Seller / Supplier":
      return "sellers";
    case "Enthusiast":
      return "enthusiasts";
    default:
      return "general";
  }
};

const starterListings: Listing[] = [
  {
    id: "listing-1",
    name: "Live Catfish",
    category: "Fish",
    price: 2500,
    description: "Fresh live catfish available for pickup.",
    seller: "Green Valley Farm",
    status: "available",
    emoji: "🐟",
  },
  {
    id: "listing-2",
    name: "Catfish Feed (15kg)",
    category: "Feed",
    price: 28000,
    description: "Floating feed suitable for growing catfish.",
    seller: "AgroFeed Ltd",
    status: "available",
    emoji: "🌾",
  },
  {
    id: "listing-3",
    name: "Catfish Fingerlings",
    category: "Fingerlings",
    price: 75,
    description: "Healthy fingerlings from a hatchery.",
    seller: "FreshFinger Hatchery",
    status: "available",
    emoji: "🐠",
  },
  {
    id: "listing-4",
    name: "Water Quality Test Kit",
    category: "Equipment",
    price: 18500,
    description: "Test pH and basic pond water conditions.",
    seller: "AquaTech Supplies",
    status: "available",
    emoji: "🧪",
  },
  {
    id: "listing-5",
    name: "Pond Health Consultation",
    category: "Services",
    price: 10000,
    description: "Professional pond assessment and advice.",
    seller: "Dr. Emmanuel",
    status: "available",
    emoji: "🩺",
  },
  {
    id: "listing-6",
    name: "Pond Aerator",
    category: "Equipment",
    price: 65000,
    description: "Aeration equipment for improved oxygenation.",
    seller: "AquaTech Supplies",
    status: "available",
    emoji: "💧",
  },
];

const starterMessages: Message[] = [
  {
    id: "msg-1",
    sender: "FishLink Team",
    role: "Community",
    text: "Welcome. Choose a group above and join the conversation.",
    date: "Today",
    group: "general",
  },
  {
    id: "msg-2",
    sender: "Emmanuel",
    role: "Fish Farmer",
    text: "My pond water became cloudy after feeding. Any suggestions?",
    date: "Today",
    group: "farmers",
  },
  {
    id: "msg-3",
    sender: "Tunde",
    role: "Fish Farmer",
    text: "Check the amount of feed and remove any uneaten feed.",
    date: "Today",
    group: "farmers",
  },
  {
    id: "msg-4",
    sender: "Dr. Emmanuel",
    role: "Veterinary Doctor",
    text: "Good water quality is important. Check dissolved oxygen and ammonia if possible.",
    date: "Yesterday",
    group: "veterinary",
  },
  {
    id: "msg-5",
    sender: "Ebere",
    role: "Fish Farmer",
    text: "What signs should I watch for when fish stop feeding?",
    date: "Yesterday",
    group: "veterinary",
  },
  {
    id: "msg-6",
    sender: "AgroFeed Ltd",
    role: "Seller / Supplier",
    text: "We have floating feed suitable for grow-out ponds. Ask about pellet sizes.",
    date: "Yesterday",
    group: "sellers",
  },
  {
    id: "msg-7",
    sender: "Tola",
    role: "Enthusiast",
    text: "I am planning a small backyard pond. What species is easiest to start with?",
    date: "Yesterday",
    group: "enthusiasts",
  },
];

const initialData: AppData = {
  user: null,
  language: "en",
  farms: [],
